head.script:
scwin.onpageload = function() {
    dataList1.insertRow();
    var j1 = dataList1.getRowJSON();
    var j2 = [];
    for (var i = 0; i < 10; i++) {
        var tmp = {};
        for (var item in j1) {
            if (item == "rowStatus" || item == "col1") continue;
            if (item == "col2") tmp[item] = (i + 1) * 1000;
            if (item == "col3") {
                tmp[item] = "T"; //(i%2 == 0) ?  "T" : "F";
            }
        }
        j2.push(tmp);
    }
    dataList1.setJSON(j2);
    var colArr = dataList1.getColData("col2");
    //console.time("scwin.sumData");
    scwin.sumData = scwin.colDataSum(colArr);
    //console.timeEnd("scwin.sumData");
    gridView1.setFooterValue("column16", scwin.sumData);
};
scwin.onpageunload = function() {};
scwin.colDataSum = function(colArr) {
    var _arr = colArr;
    return _arr.reduce(function(total, value, currentIndex) {
        //console.log("total: ",total," value: ",value," curIdx: ",currentIndex);
        return total + value;
    }, 0);
};
scwin.gridView1_onviewchange = function(info) {
    //console.log(info);
    if (info.colIndex == 2) { //checkbox 컬럼인 경우.
        //console.time("onviewchange");
        var chkIndex = gridView1.getCheckedIndex(info.colIndex);
        var ftData = 0;
        if (dataList1.getRowCount() == chkIndex.length) {
            ftData = scwin.colDataSum(dataList1.getColData("col2"));
        } else {
            for (var i = 0; i < chkIndex.length; i++) {
                ftData += dataList1.getCellData(chkIndex[i], "col2");
            }
        }
        gridView1.setFooterValue("column16", ftData + "");
        //console.timeEnd("onviewchange");
    }
};
scwin.gridView1_onheaderclick = function(headerId) {
    //console.log("headerId: ",headerId);
    if (headerId == "column3") {
        var ftData = 0;
        //console.time("scwin.gridView1_onheaderclick");
        if (gridView1.getHeaderValue(headerId)) {
            ftData = scwin.colDataSum(dataList1.getColData("col2"));
        }
        gridView1.setFooterValue("column16", ftData + "");
        //console.timeEnd("scwin.gridView1_onheaderclick");
    }
};
scwin.custFormatter = function(data, formattedData, rowIndex, colIndex) {
    return "<strong>" + data + "</strong>";
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-sequence', {
        sequence: '123123'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_gridView1__col1', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#G_gvSparePartKitByOfficeSetup__kitSum0Value', 'key-combo', {
        combo: 'DEL'
    });
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkColor = function(id, rgb) {
    var element = WebSquare.wUnit.getDomById($p.id + id)
    var color = WebSquare.wUnit.getJq($(element).children()[0]).css("color");
    return color == rgb;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_1_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#gridView1_cell_1_2 input').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_1_0').innerText == '123123'", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /*
     * footer 총 합계 계산.
     * 체크박스 전체선택 시 단순 반복문보다 10배 이상 빠릅니다. (10000건, IE11 기준)
     */
    //for
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
